import type { AudioClipPlayer } from "@lexi/core/platform";

/**
 * Lexi's recorded pronunciations (`/audio/<voice>/<key>.mp3`, generated by
 * `scripts/generate-audio.ts`) behind the core's `AudioClipPlayer` contract.
 */
export function createWebClipPlayer(base = "/audio"): AudioClipPlayer {
  let index: Promise<readonly string[]> | null = null;
  let current: { audio: HTMLAudioElement; settle: (ok: boolean) => void } | null = null;

  return {
    loadIndex() {
      index ??= fetch(`${base}/index.json`)
        .then((response) => {
          if (!response.ok) throw new Error(`audio index: ${response.status}`);
          return response.json() as Promise<{ keys: string[] }>;
        })
        .then((data) => data.keys)
        .catch((error: unknown) => {
          index = null; // try again later (offline, deploy in progress…)
          throw error;
        });
      return index;
    },

    play(clip, { rate, onDone, onError }) {
      current?.settle(true);
      const audio = new Audio(`${base}/${clip}.mp3`);
      audio.preservesPitch = true;
      audio.playbackRate = rate;
      let settled = false;
      const settle = (ok: boolean) => {
        if (settled) return;
        settled = true;
        if (current?.audio === audio) current = null;
        if (ok) onDone();
        else onError();
      };
      current = { audio, settle };
      audio.onended = () => settle(true);
      audio.onerror = () => settle(false);
      audio.play().catch((error: unknown) => {
        // Interrupted by a newer clip: that is a normal end, not a failure.
        settle(error instanceof DOMException && error.name === "AbortError");
      });
    },

    stop() {
      if (!current) return;
      const { audio, settle } = current;
      audio.pause();
      settle(true);
    },
  };
}
